"use strict";

// The catalog is generated by `pkguard dump-catalog`, so the file is rewritten
// byte-for-byte by CI's freshness check. Patch the version in place rather than
// re-serialising the JSON, which would risk changing the formatting.
const TOP_LEVEL_VERSION = /^ {2}"version": "([^"]+)"/m;

exports.readVersion = (contents) => {
  const match = contents.match(TOP_LEVEL_VERSION);
  if (match === null) {
    throw new Error("catalog.json has no top-level version");
  }
  return match[1];
};

exports.writeVersion = (contents, version) =>
  contents.replace(TOP_LEVEL_VERSION, () => `  "version": "${version}"`);
